  'گروه\u200cهای تحقیق و بازرسهای هیأت عالی نظارت در مدتی که در مشاغل یاد شده\u200cانجام وظیفه می\u200cکنند از فوق '
  'العاده شغل اضافی علاوه برفوق العاده شغل استحقاقی تا پنجاه درصد برخوردار می\u200cشوندکه در هر حال میزان فوق العاده '
